import java.util.*;

import javax.print.DocFlavor.STRING;
public class Sumofdigit {
    public static void main(String[] args){
        Scanner sc=new Scanner(System.in);
        int n=sc.nextInt();
        String s=sc.nextLine();
        
        
        System.out.println(n);
        System.out.println(s);
    }
    
}
